public str getName()
{
    return fieldPName(RetailSalesTable, ChannelReferenceId);
}

public Set getAllowedValues()
{
    RetailSalesTable    retailSalesTable;
    var                 ret = new Set(Types::String);

    while select ChannelReferenceId from retailSalesTable
        group by ChannelReferenceId
    {
        ret.add(retailSalesTable.ChannelReferenceId);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesTable, ChannelReferenceId));
    qbr.value(queryValue(_value));
}
